# Fix Windows path separators in the product architecture guard (false-positive on Windows).
# The guard used forward-slash matching on relative() output, which returns backslashes on
# Windows -> pg/SQL files were wrongly flagged. This normalizes the path. Test-file only;
# no change to src/product, no logic/intelligence change.
# Run from project root:  powershell -ExecutionPolicy Bypass -File .\fix-windows-paths.ps1
$ErrorActionPreference = "Stop"
$path = "tests/architecture/productBoundaries.test.ts"
$b64 = ""
$bytes = [System.Convert]::FromBase64String($b64)
[System.IO.File]::WriteAllBytes((Join-Path (Get-Location) $path), $bytes)
Write-Host "  fixed $path (Windows path normalization)" -ForegroundColor Green
Write-Host ""
Write-Host "Re-running the full suite..." -ForegroundColor Cyan
npx vitest run
Write-Host ""
Write-Host "Expected now: 0 failed. (~796 passed + 1 skipped)" -ForegroundColor Yellow
